	request: Request,
	content: McpSiteContent,
	jsonResponse: McpJsonResponse,
): Promise<Response> {
	const method = request.method.toUpperCase();

	if (method === "OPTIONS") {
		return mcpPreflightResponse();
	}

	if (method !== "POST") {
		// Streamable HTTP: GET is optional SSE. This read-only server does not
